VAR_OUTPUT
    power : REAL := 0.0;
    correction : REAL := 0.0;
    fault : BOOL := FALSE;
END_VAR

VAR
    ePrev : REAL := 0.0;
    hasHistory : BOOL := FALSE;
    prevEnableAndNoFault : BOOL := FALSE;
    prevResetBtn : BOOL := FALSE;
END_VAR

VAR
    risingReset : BOOL;
    e : REAL;
    de : REAL;
    x : REAL;
    y : REAL;
    muNx : REAL;
    muZx : REAL;
